class Solution {
public:
    int getLastMoment(int n, vector<int>& left, vector<int>& right) {
        int ans = 0;
        for (int x : left) {
            if (x > ans) ans = x;
        }
        for (int x : right) {
            int t = n - x;
            if (t > ans) ans = t;
        }
        return ans;
    }
};
